INSERT OR IGNORE INTO textos (id, chave, valor, nota, grupo, actualizado_em) VALUES ('b1f4853a-5e52-4154-bdf9-6ed39fab4f31', 'ativo.descricao', '{"pt":"O que faz uma obra de arte valorizar, o que a galeria avalia antes de representar um artista, e o que ninguém honesto lhe pode prometer.","en":"What makes a work of art appreciate, what the gallery assesses before representing an artist, and what nobody honest can promise you.","es":"Qué hace que una obra de arte se revalorice, qué evalúa la galería antes de representar a un artista, y lo que nadie honesto puede prometerle."}', 'Descrição da página nos motores de busca.', 'ativo', 1790258103);
