INSERT OR IGNORE INTO textos (id, chave, valor, nota, grupo, actualizado_em) VALUES ('11a9539f-0e94-4f2b-8402-416b00e0e970', 'descarregar.vazio', '{"pt":"Ainda não há documentos publicados. Assim que o catálogo estiver carregado, aparece aqui.","en":"No documents published yet. As soon as the catalogue is uploaded, it appears here.","es":"Todavía no hay documentos publicados. En cuanto el catálogo esté cargado, aparecerá aquí."}', 'O que o visitante lê enquanto não houver documentos publicados.', 'descarregáveis', 1790258103);
--> statement-breakpoint
